setupCode:
@use '@angular/material' as mat;

:root {
  @include mat.theme((
    color: (
      primary: mat.$violet-palette,
      theme-type: light,
    ),
    typography: Roboto,
    density: 0,
  ));
}

.dark-theme {
  @include mat.theme((
    color: (
      primary: mat.$violet-palette,
      theme-type: dark,
    ),
    typography: Roboto,
    density: 0,
  ));
}
